// Oeste Kicker — Mesa theme (v0.2.0).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Mesa tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/mesa/src/index.js
// Docs: https://oeste.hiddeninwest.com/mesa/#/components/kicker

const MONO = "font-[ui-monospace,'SF_Mono','Cascadia_Code',Menlo,Consolas,monospace]";

const FAINT = "text-[#8a8e93] dark:text-[#6e6455]";

export function Kicker({ children, variant = "default" }) {
  return (
    <p className={`${MONO} text-[11px] font-bold uppercase tracking-[0.26em] ${variant === "faint" ? FAINT : "text-[#8a1f2b] dark:text-[#c9404f]"}`}>{children}</p>
  );
}
